-- v70: 회계 전용 D1의 담당부서 표기를 현행 직제로 정비합니다.
-- 기존 통합 `대외협력·사회공헌` 자료는 직책정보가 없어 국제교류국으로 이관합니다.
UPDATE accounting_entities SET department_path=CASE WHEN department_path IS NULL OR TRIM(department_path)='' THEN department_path WHEN TRIM(department_path) IN ('사무국','사무처') THEN '사무처' WHEN TRIM(department_path) IN ('재정국','준법윤리국','국제교류국','문화홍보국','사회공헌국') THEN '사무처 - ' || TRIM(department_path) WHEN TRIM(department_path) IN ('재정·회계','사무국 - 재정·회계','사무처 - 재정·회계','사무국(재정·회계)','사무처(재정·회계)') THEN '사무처 - 재정국' WHEN TRIM(department_path) IN ('준법·윤리','사무국 - 준법·윤리','사무처 - 준법·윤리','사무국(준법·윤리)','사무처(준법·윤리)') THEN '사무처 - 준법윤리국' WHEN TRIM(department_path) IN ('문화·홍보','사무국 - 문화·홍보','사무처 - 문화·홍보','사무국(문화·홍보)','사무처(문화·홍보)') THEN '사무처 - 문화홍보국' WHEN TRIM(department_path) IN ('대외협력·사회공헌','사무국 - 대외협력·사회공헌','사무처 - 대외협력·사회공헌','사무국(대외협력·사회공헌)','사무처(대외협력·사회공헌)') THEN '사무처 - 국제교류국' ELSE REPLACE(department_path,'사무국','사무처') END WHERE department_path IS NOT NULL AND (department_path LIKE '%사무국%' OR TRIM(department_path) IN ('재정·회계','준법·윤리','대외협력·사회공헌','문화·홍보','재정국','준법윤리국','국제교류국','문화홍보국','사회공헌국'));
